### Required Tag Validation — `terraform test`

Per STD-INFRA-IAC-008, formation unit tests **must** assert that the required tag keys are present in mock outputs:

```hcl
# iac/terraform/formations/aws/tests/unit.tftest.hcl

run "required_tags_present" {
  command = plan

  variables {
    common = {
      tags = {
        Company       = "Gainwell"
        Email         = "test@gainwelltech.com"
        CloudProvider = "AWS"
        Account       = "test-account"
        BillingCode   = "CC-TEST"
        ManagedBy     = "terraform:mmes-cms-mbr-dev"
        Tenant        = "cm"
      }
    }
  }

  assert {
    condition     = contains(keys(var.common.tags), "ManagedBy")
    error_message = "ManagedBy tag is required but missing from common.tags"
  }

  assert {
    condition     = contains(keys(var.common.tags), "Tenant")
    error_message = "Tenant tag is required but missing from common.tags"
  }

  assert {
    condition     = startswith(var.common.tags["ManagedBy"], "terraform:")
    error_message = "ManagedBy tag value must follow the format 'terraform:<deployment_name>'"
  }
}
```

