#### Example 1: Standard `common-includes.hcl` for MMES CMS MBR

```hcl
# iac/terraform/deployments/aws/dev/common-includes.hcl

locals {
  env_short_name = "dev"

  company_tags = {
    Company     = "Gainwell"
    Email       = "mmes-cms-mbr@gainwelltech.com"
    BillingCode = "CC-88421"
    Tenant      = "cm"
  }

  cloud_tags = {
    CloudProvider = "AWS"
    Account       = get_aws_account_alias()
  }

  env_tags = {
    Environment = local.env_short_name
  }

  managed_by_tag = {
    ManagedBy = "terraform:${basename(get_terragrunt_dir())}"
  }

  common = {
    tags = merge(
      local.company_tags,
      local.cloud_tags,
      local.env_tags,
      local.managed_by_tag,
    )
    env        = local.env_short_name
    region     = "us-east-1"
    account_id = get_aws_account_id()
  }
}
```

**Resulting `ManagedBy` value** (when applied from `iac/terraform/deployments/aws/dev/mmes-cms-mbr-dev/`): `terraform:mmes-cms-mbr-dev`
